-- =============================================================================
-- Step 1 Acceptance Suite Schema Fixture (15 tables + 1 view + 1 excluded table)
-- Covers every hard case specified in docs/STEP1_CLONE_PLAN.md §2.1
-- =============================================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

CREATE TYPE public.enrollment_status AS ENUM ('active', 'dropped', 'paused', 'completed');

-- Excluded plumbing table (must be ignored by lab clone)
CREATE TABLE public.schema_migrations (
    version text PRIMARY KEY,
    applied_at timestamp with time zone DEFAULT now() NOT NULL
);

-- 1. 2-row table with text PK and free-text column
CREATE TABLE public.region_config (
    region_code text PRIMARY KEY,
    description text NOT NULL,
    CONSTRAINT ck_region_code CHECK (region_code ~ '^[A-Za-z0-9_]{2,24}$')
);

-- 2. 5-row table with identity PK, allowlisted low-card column, and non-allowlisted low-card column
CREATE TABLE public.subscription_tier (
    tier_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tier_level text NOT NULL,
    internal_bucket text NOT NULL,
    monthly_fee numeric(8,2) NOT NULL,
    CONSTRAINT ck_tier_fee CHECK (monthly_fee >= 0)
);

-- 3. Table with uuid PK, regex CHECK, char_length(btrim) CHECK, NOT NULL text[] + cardinality CHECK,
--    NOT NULL jsonb, RLS enabled + policy, trigger, and COMMENT ON with canary
CREATE TABLE public.organization (
    org_id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    org_name text NOT NULL,
    org_slug text NOT NULL,
    region_code text NOT NULL REFERENCES public.region_config(region_code),
    tier_id integer NOT NULL REFERENCES public.subscription_tier(tier_id),
    tags text[] NOT NULL,
    settings_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT uq_organization_slug UNIQUE (org_slug),
    CONSTRAINT ck_organization_name CHECK (char_length(btrim(org_name)) BETWEEN 3 AND 80),
    CONSTRAINT ck_organization_slug CHECK (org_slug ~ '^[A-Za-z0-9_-]{3,40}$'),
    CONSTRAINT ck_organization_tags CHECK (cardinality(tags) BETWEEN 1 AND 3)
);

ALTER TABLE public.organization ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organization FORCE ROW LEVEL SECURITY;
CREATE POLICY org_isolation_policy ON public.organization
    USING (org_slug <> 'blocked_by_rls');

CREATE OR REPLACE FUNCTION public.trg_noop_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_organization_noop
    BEFORE INSERT OR UPDATE ON public.organization
    FOR EACH ROW EXECUTE FUNCTION public.trg_noop_fn();

COMMENT ON TABLE public.organization IS 'Organization table with CANARY_7f3a in comment';
COMMENT ON COLUMN public.organization.org_name IS 'Organization name CANARY_7f3a';

-- 4. Self-referencing FK and multi-column UNIQUE
CREATE TABLE public.department (
    dept_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id uuid NOT NULL REFERENCES public.organization(org_id),
    parent_dept_id integer REFERENCES public.department(dept_id),
    dept_code text NOT NULL,
    dept_title text NOT NULL,
    CONSTRAINT uq_department_org_code UNIQUE (org_id, dept_code),
    CONSTRAINT ck_department_code CHECK (dept_code ~ '^[A-Za-z0-9_]{2,20}_[0-9]{1,4}$')
);

-- 5 & 6. FK cycle broken by a nullable column (research_team <-> team_member)
CREATE TABLE public.research_team (
    team_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id uuid NOT NULL REFERENCES public.organization(org_id),
    team_title text NOT NULL,
    lead_member_id integer
);

CREATE TABLE public.team_member (
    member_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id integer NOT NULL REFERENCES public.research_team(team_id),
    member_email text NOT NULL,
    role_note text
);

ALTER TABLE public.research_team
    ADD CONSTRAINT fk_research_team_lead
    FOREIGN KEY (lead_member_id) REFERENCES public.team_member(member_id);

-- 7. Composite PK, single-column range CHECK, and multi-column date CHECK (end_date >= start_date)
CREATE TABLE public.program (
    org_id uuid NOT NULL REFERENCES public.organization(org_id),
    program_id integer NOT NULL,
    program_title text NOT NULL,
    credits integer NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    PRIMARY KEY (org_id, program_id),
    CONSTRAINT ck_program_credits CHECK (credits BETWEEN 1 AND 12),
    CONSTRAINT ck_program_dates CHECK (end_date >= start_date)
);

-- 8. Composite PK (3 cols) and composite FK (2 cols)
CREATE TABLE public.program_unit (
    org_id uuid NOT NULL,
    program_id integer NOT NULL,
    unit_id integer NOT NULL,
    unit_summary text NOT NULL,
    PRIMARY KEY (org_id, program_id, unit_id),
    CONSTRAINT fk_program_unit_program
        FOREIGN KEY (org_id, program_id) REFERENCES public.program(org_id, program_id)
);

-- 9. Two composite FKs on one table sharing columns (org_id, program_id)
CREATE TABLE public.unit_assignment (
    assignment_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id uuid NOT NULL,
    program_id integer NOT NULL,
    unit_id integer NOT NULL,
    weight_pct numeric(5,2) NOT NULL,
    CONSTRAINT fk_unit_assignment_program
        FOREIGN KEY (org_id, program_id) REFERENCES public.program(org_id, program_id),
    CONSTRAINT fk_unit_assignment_unit
        FOREIGN KEY (org_id, program_id, unit_id) REFERENCES public.program_unit(org_id, program_id, unit_id),
    CONSTRAINT ck_unit_assignment_weight CHECK (weight_pct >= 5.0 AND weight_pct <= 100.0)
);

-- 10. Parent table for implicit FK target (`code`) AND repairable multi-term CHECK (A13)
CREATE TABLE public.course (
    course_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id uuid NOT NULL REFERENCES public.organization(org_id),
    code text NOT NULL UNIQUE,
    min_seats integer NOT NULL,
    max_seats integer NOT NULL,
    CONSTRAINT ck_course_min_seats CHECK (min_seats BETWEEN 10 AND 30),
    CONSTRAINT ck_course_max_seats CHECK (max_seats BETWEEN 20 AND 60),
    CONSTRAINT ck_course_seat_gap CHECK ((max_seats - min_seats) >= 15)
);

-- 11. Child of `course` (verifies zero orphans under A13 repaired parent) + nullable FK
CREATE TABLE public.course_section (
    section_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    course_id integer NOT NULL REFERENCES public.course(course_id),
    advisor_member_id integer REFERENCES public.team_member(member_id),
    room_label text NOT NULL
);

-- 12. Student table with PII-named date/numeric/text columns, enum, CHECK IN, and partial unique index
CREATE TABLE public.student (
    student_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id uuid NOT NULL REFERENCES public.organization(org_id),
    email varchar(120) NOT NULL,
    full_name text NOT NULL,
    birth_date date NOT NULL,
    phone_number bigint NOT NULL,
    status public.enrollment_status NOT NULL,
    scholarship_tier text NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_student_scholarship CHECK (scholarship_tier IN ('none', 'half', 'full'))
);

CREATE UNIQUE INDEX uq_student_active_email
    ON public.student (org_id, email)
    WHERE (is_deleted = false);

-- 13. Composite PK & FK junction table
CREATE TABLE public.enrollment (
    student_id integer NOT NULL REFERENCES public.student(student_id),
    section_id integer NOT NULL REFERENCES public.course_section(section_id),
    enrolled_on date NOT NULL,
    PRIMARY KEY (student_id, section_id)
);

-- 14. Table with undeclared implicit FK (`course_code -> course.code`),
--     PII-veto-overridden categorical column (`card_type`),
--     and one deliberately unsatisfiable CHECK constraint (must become degraded, exit code 2)
CREATE TABLE public.payment (
    payment_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id integer NOT NULL REFERENCES public.student(student_id),
    course_code text NOT NULL,
    card_type text NOT NULL,
    amount_cents integer NOT NULL,
    audit_memo text NOT NULL,
    CONSTRAINT ck_payment_amount CHECK (amount_cents >= 100 AND amount_cents <= 500000),
    CONSTRAINT ck_payment_unsatisfiable_hash CHECK (md5(audit_memo) = 'ddd792548211ec71b2ceae0c0475257c')
);

-- 15. Large table (> 1,000 target rows at scale 0.1) for A11 first-1,000-rows verification
CREATE TABLE public.activity_event (
    event_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id integer NOT NULL REFERENCES public.student(student_id),
    event_kind text NOT NULL,
    duration_sec integer NOT NULL,
    ref_note text,
    CONSTRAINT ck_activity_duration CHECK (duration_sec >= 1 AND duration_sec <= 7200)
);

-- View to test view fidelity (A2)
CREATE OR REPLACE VIEW public.v_active_students AS
SELECT student_id, org_id, status, scholarship_tier
FROM public.student
WHERE is_deleted = false;
